#!/usr/bin/env bash
# Adds full support for the "configure" command_type - the Admin Panel's
# "Configure what starts the kiosk process" form (kiosk_configure route)
# queues a 'configure' command on the SAME InstanceCommand queue as
# start/stop/restart, carrying kiosk_start_command/kiosk_working_dir/
# kiosk_health_check_url/kiosk_health_check_command in its payload. The
# Agent's commands.py from the previous fix in this series treated
# 'configure' as unsupported (a wrong assumption that it went through the
# separate /instances/config version-push channel instead) - so clicking
# that button would queue a command the Agent immediately acked as
# "Unsupported command_type: 'configure'".
#
# Changes:
#   - ProcessSupervisor now accepts command=None and adds is_configured() +
#     reconfigure() (agent/process_supervisor.py) - start()/restart() are
#     safe no-ops when unconfigured (verified: does not raise, does not
#     regress agent/update_manager.py's existing "supervisor is not None"
#     restart-after-update / rollback flow), and start_watchdog() is now
#     idempotent.
#   - agent/main.py now always constructs ONE ProcessSupervisor for the
#     whole run (never None) and always starts its watchdog, so a
#     'configure' command has something live to reconfigure() instead of
#     needing to hand a newly-built supervisor to already-running threads.
#   - agent/commands.py handles 'configure': persists the new fields to
#     settings.json, then reconfigure()+restart()s the running supervisor;
#     an empty kiosk_start_command stops and clears it. start/stop/restart
#     now check supervisor.is_configured() instead of "is supervisor None".
#
# Verified end-to-end against a fake ApiClient + a real "sleep 30"
# subprocess: unconfigured stop fails cleanly, configure starts and
# persists to disk, stop/start/restart all operate on the same live
# process, restart actually replaces the pid, and configure-to-clear tears
# it down - plus confirmed update_manager restarting an unconfigured
# supervisor stays a no-op (does not raise).
#
# Updates BOTH this repo's own ./agent, ./requirements.txt, and
# ./service_files (what build_msi_selfcontained.sh / build_msi.sh / the exe
# builder stage from directly) AND the served
# app/static/installers/opslab-agent.tar.gz (what install.ps1 downloads for
# a fresh enrollment). Includes all fixes from earlier in this series
# (commands channel, sys.path fix, missing requests dependency) in case
# this is being run standalone.
#
# Run from inside /root/admin_panel (or wherever this repo lives on the VPS).
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt service_files; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

echo "==> [1/3] Extracting fixed agent/ + requirements.txt + service_files/ into this repo"
TMP_EXTRACT="$(mktemp -d)"
base64 -d > "$TMP_EXTRACT/opslab-agent.tar.gz" << 'B64_EOF_MARKER'

B64_EOF_MARKER
tar -xzf "$TMP_EXTRACT/opslab-agent.tar.gz" -C "$TMP_EXTRACT"

if ! grep -q "def reconfigure" "$TMP_EXTRACT/agent/process_supervisor.py" || \
   ! grep -q "_apply_configure" "$TMP_EXTRACT/agent/commands.py"; then
    echo "    ERROR: fix not found in the extracted payload!"
    rm -rf "$TMP_EXTRACT"
    exit 1
fi

rm -f agent/config.py.bak
cp -f "$TMP_EXTRACT/agent/"*.py agent/
cp -f "$TMP_EXTRACT/service_files/windows/opslab_agent_service.py" service_files/windows/opslab_agent_service.py
cp -f "$TMP_EXTRACT/requirements.txt" requirements.txt
echo "    Updated agent/*.py, service_files/windows/opslab_agent_service.py, and requirements.txt in this repo."

echo "==> [2/3] Rewriting app/static/installers/opslab-agent.tar.gz"
cp -f "$TMP_EXTRACT/opslab-agent.tar.gz" app/static/installers/opslab-agent.tar.gz
rm -rf "$TMP_EXTRACT"

echo "==> [3/3] Verifying the served tarball"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    tarball is readable"
VERIFY_DIR="$(mktemp -d)"
tar -xzf app/static/installers/opslab-agent.tar.gz -C "$VERIFY_DIR"
if grep -q "def reconfigure" "$VERIFY_DIR/agent/process_supervisor.py" && grep -q "_apply_configure" "$VERIFY_DIR/agent/commands.py"; then
    echo "    Confirmed: configure support is present in the packaged tarball."
else
    echo "    ERROR: fix not found in the packaged tarball!"
    rm -rf "$VERIFY_DIR"
    exit 1
fi
rm -rf "$VERIFY_DIR"

echo ""
echo "IMPORTANT: this changes agent behavior for ALREADY-RUNNING instances too,"
echo "not just future enrollments - but they only pick it up on their own next"
echo "self-update (Releases/Rollouts) or a manual reinstall, same as the earlier"
echo "fixes in this series. Existing instances keep acking 'configure' as"
echo "unsupported until then."
echo ""
echo "Restart the admin panel app itself (needed this time - Python module code"
echo "changed, not just what install.ps1 downloads):"
echo "    pkill -f 'admin_panel/run.py'; fuser -k 6090/tcp 2>/dev/null"
echo "    cd /root/admin_panel && source venv/bin/activate && nohup python run.py > app.log 2>&1 & disown"
echo ""
echo "Then on Ewan (or any Windows machine), re-run enrollment with a fresh token"
echo "to pick up the fix immediately:"
echo "    irm https://kiosksys.opslabsystems.cloud/install.ps1 -OutFile install.ps1; .\\install.ps1 -Token <fresh-token> -AdminUrl https://kiosksys.opslabsystems.cloud"
echo "After that, 'Configure what starts the kiosk process' + Start/Stop/Restart"
echo "in the instance detail page will all actually work."
